#!/bin/bash
# stdlib-docs.sh -- docs/stdlib/ generated by scribe (`fid doc`) from
# stdlib/*.fd, for each release (docs/roadmap/release-roadmap.md N10;
# docs/reference/releasing.md step 4).
#
#   scripts/stdlib-docs.sh            regenerate docs/stdlib/ (a Markdown page
#                                     per module and index.md; README.md, the
#                                     hand-written overview, is left alone)
#   scripts/stdlib-docs.sh --check    generate into a scratch directory and
#                                     compare with docs/stdlib/: exit 1 when a
#                                     page is missing, stale, or names a module
#                                     the stdlib no longer has
#   scripts/stdlib-docs.sh --zip      also pack the pages into
#                                     build/fides-stdlib-docs.zip (or .tar.gz
#                                     without zip) to attach to the release
#
#   FID=<fid>   the compiler (default release/fid.exe, else release/fid)
#
# Only the top-level stdlib/*.fd modules are documented: the runtimes in
# stdlib/pe_runtime/ and stdlib/linux_runtime/ are the compiler's, not API.
set -u
cd "$(dirname "$0")/.." || exit 1
ROOT="$(pwd)"
FID="${FID:-}"
if [ -z "$FID" ]; then
  if [ -x release/fid.exe ]; then FID=release/fid.exe; else FID=release/fid; fi
fi
case "$FID" in
  /*|[A-Za-z]:*) ;;
  *) FID="$ROOT/$FID" ;;
esac
MODE=write
ZIP=0
for a in "$@"; do
  case "$a" in
    --check) MODE=check ;;
    --zip) ZIP=1 ;;
    *) echo "usage: $0 [--check] [--zip]" >&2; exit 2 ;;
  esac
done

OUT="$ROOT/build/stdlib-docs"
rm -rf "$OUT"
mkdir -p "$OUT/src"
# `fid doc <dir>` documents a directory recursively: give it the top-level
# modules only
cp stdlib/*.fd "$OUT/src/"
if ! "$FID" doc "$OUT/src" --format markdown --output "$OUT/md" > "$OUT/doc.log" 2>&1; then
  echo "stdlib-docs: fid doc failed (see $OUT/doc.log)"
  exit 1
fi
pages=$(ls "$OUT/md"/*.md 2> /dev/null | wc -l)
modules=$(ls stdlib/*.fd | wc -l)
if [ "$pages" -le "$modules" ]; then
  # a page per module plus index.md
  echo "stdlib-docs: $pages pages for $modules modules (see $OUT/doc.log)"
  exit 1
fi
echo "stdlib-docs: $(cat "$OUT/doc.log")"

if [ "$MODE" = check ]; then
  bad=0
  for f in "$OUT/md"/*.md; do
    b="$(basename "$f")"
    if [ ! -f "docs/stdlib/$b" ]; then
      echo "  missing  docs/stdlib/$b"; bad=1
    elif ! cmp -s "$f" "docs/stdlib/$b"; then
      echo "  stale    docs/stdlib/$b"; bad=1
    fi
  done
  for f in docs/stdlib/*.md; do
    b="$(basename "$f")"
    [ "$b" = README.md ] && continue
    if [ ! -f "$OUT/md/$b" ]; then
      echo "  extra    docs/stdlib/$b (no such module now)"; bad=1
    fi
  done
  if [ "$bad" = 0 ]; then
    echo "stdlib-docs: docs/stdlib/ is up to date"
  else
    echo "stdlib-docs: docs/stdlib/ differs: run scripts/stdlib-docs.sh"
  fi
  exit "$bad"
fi

mkdir -p docs/stdlib
cp "$OUT/md"/*.md docs/stdlib/
for f in docs/stdlib/*.md; do
  b="$(basename "$f")"
  [ "$b" = README.md ] && continue
  [ -f "$OUT/md/$b" ] || echo "  note: docs/stdlib/$b documents no current module (remove it by hand)"
done
echo "stdlib-docs: wrote $pages pages to docs/stdlib/"

if [ "$ZIP" = 1 ]; then
  mkdir -p build
  if command -v zip > /dev/null; then
    (cd "$OUT/md" && zip -q -r "$ROOT/build/fides-stdlib-docs.zip" .)
    echo "stdlib-docs: build/fides-stdlib-docs.zip"
  else
    tar -czf build/fides-stdlib-docs.tar.gz -C "$OUT/md" .
    echo "stdlib-docs: build/fides-stdlib-docs.tar.gz"
  fi
fi
exit 0
